<script setup lang="ts">
import { computed, onMounted, ref } from "vue"; import { useRoute } from "vue-router"; import { api } from "../utils/api"; import { formatOperationTime } from "../utils/date";
const route=useRoute(); const rows=ref<any[]>([]); const loading=ref(false); const attachmentId=computed(() => Number(route.params.id)); const paths:Record<string,string>={Voucher:"/vouchers",Invoice:"/invoices",BankTransaction:"/bank",FixedAsset:"/fixed-assets",Reimbursement:"/reimbursements",Salary:"/salaries"};
async function load(){loading.value=true;try{rows.value=await api.get<any[]>(`/attachments/${attachmentId.value}/relations`);}finally{loading.value=false;}} onMounted(load);
</script>
<template><div class="page-grid"><section class="page-heading"><div><h2>附件关联对象</h2><p>同一附件可被多个业务对象共享。</p></div></section><el-card shadow="never"><el-table table-layout="auto" v-loading="loading" :data="rows" stripe><el-table-column prop="sourceType" label="来源类型"/><el-table-column prop="sourceId" label="业务对象"><template #default="{row}"><RouterLink v-if="paths[row.sourceType]" :to="paths[row.sourceType]">{{row.sourceType}} #{{row.sourceId}}</RouterLink><span v-else>{{row.sourceType}} #{{row.sourceId}}</span></template></el-table-column><el-table-column prop="relationType" label="关联类型"/><el-table-column prop="remark" label="备注"/><el-table-column label="关联时间"><template #default="{row}">{{ formatOperationTime(row.createdAt) }}</template></el-table-column></el-table></el-card></div></template>
